<script setup lang="ts">
import{ref,watch}from'vue';import{useSalesScope}from'./use-sales-scope';import{qualityStatusUrl,validQualityStatus}from'./quality-pending-status';
const props=defineProps<{staff:any;pending:any;busy:boolean}>(),emit=defineEmits(['clear','retry','access-lost','unauthorized']),status=ref<any>(null),checking=ref(false),checked=ref(false),error=ref(''),scope=useSalesScope(()=>JSON.stringify([props.staff.accountId,props.staff.employeeId,props.pending]));
watch(()=>JSON.stringify([props.staff.accountId,props.staff.employeeId,props.pending]),()=>{status.value=null;checking.value=false;checked.value=false;error.value='';},{flush:'sync'});
const known=()=>['confirmed','rejected'].includes(props.pending.phase);
async function verify(){if(props.busy||checking.value||known())return;const current=scope.begin('status');checking.value=true;checked.value=false;status.value=null;error.value='';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(qualityStatusUrl(props.pending),{credentials:'same-origin',signal:controller.signal}),v=await r.json();if(!current())return;if(!r.ok){if(r.status===401)emit('unauthorized');if(r.status===403)emit('access-lost');throw Error(v.message||'原提交核实失败。');}status.value=validQualityStatus(props.pending,v);}catch(e:any){if(current())error.value=e.message;}finally{clearTimeout(timer);if(current.active())checking.value=false;}}
function clear(){if(!props.busy&&!checking.value&&(known()||status.value?.state==='completed'))emit('clear',props.pending);}
function retry(){if(!props.busy&&!checking.value&&checked.value&&status.value?.state==='not_found'&&(!props.pending.phase||props.pending.phase==='pending')){validQualityStatus(props.pending,status.value);status.value=null;checked.value=false;emit('retry',props.pending);}}
</script>
<template><section class="b-alert warning"><template v-if="['confirmed','rejected'].includes(pending.phase)"><p>本机已记录原办理{{pending.phase==='rejected'?'被拒绝':'成功'}}，只需清理本机提示，不会重新提交。</p><button class="b-button outline" :disabled="busy" @click="clear">仅清理本机提示</button></template><template v-else><p>有一笔资料检查提交结果待核实，请先只读查询原请求。</p><button class="b-button outline" :disabled="busy||checking" @click="verify">{{checking?'正在核实…':'只读核实原提交'}}</button><p v-if="error" role="alert">{{error}}</p><template v-if="status?.state==='completed'"><p>已查到原结果 {{status.resultId}}<template v-if="status.version"> · 第{{status.version}}版</template><template v-if="status.kind==='scan'"> · 原发现{{status.found}}项，新增或重新打开{{status.count}}项</template> · {{new Date(status.completedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}。</p><button class="b-button outline" :disabled="busy||checking" @click="clear">已核对，清理本机提示</button></template><template v-else-if="status?.state==='not_found'"><p>暂未见成功凭据，可能仍在处理、未提交或已回滚，不能据此认定未保存。</p><label class="b-checkbox"><input type="checkbox" v-model="checked" :disabled="busy||checking"/>已核对，沿原请求号和原内容重试</label><button class="b-button outline" :disabled="busy||checking||!checked" @click="retry">重试原提交</button></template></template></section></template>
